// Inspect generated bytes, independently of Forge's exit status. Windows x64 only.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { promisify } = require('node:util');
const asar = require('@electron/asar');
const yauzl = require('yauzl');
const { getCurrentFuseWire, FuseV1Options } = require('@electron/fuses');
const metadata = require('../package.json');
const packageDirectory = path.resolve(__dirname, '../out', `${metadata.productName}-win32-x64`);
const zipFile = path.resolve(__dirname, '../out/make/zip/win32/x64', `${metadata.productName}-win32-x64-${metadata.version}.zip`);
function filesUnder(directory, prefix = '') {
  return fs.readdirSync(directory, { withFileTypes: true }).flatMap(entry => {
    const relative = prefix + entry.name;
    assert.ok(!entry.isSymbolicLink(), `Unexpected link: ${relative}`);
    return entry.isDirectory() ? filesUnder(path.join(directory, entry.name), `${relative}/`) : [relative];
  });
}
function requireFile(directory, relative, minimum = 1) {
  const file = path.join(directory, relative);
  assert.ok(fs.statSync(file).isFile() && fs.statSync(file).size >= minimum, `Missing/incomplete ${file}`);
  return file;
}
async function verifyPackage(directory = packageDirectory) {
  const executable = requireFile(directory, `${metadata.productName}.exe`, 1000000);
  const header = fs.readFileSync(executable).subarray(0, 4096);
  assert.equal(header.toString('ascii', 0, 2), 'MZ');
  assert.equal(header.readUInt16LE(header.readUInt32LE(0x3c) + 4), 0x8664, 'PE must be Windows x64');
  for (const file of ['resources/app.asar', 'icudtl.dat', 'resources.pak', 'snapshot_blob.bin', 'v8_context_snapshot.bin',
    'chrome_100_percent.pak', 'chrome_200_percent.pak', 'ffmpeg.dll', 'd3dcompiler_47.dll', 'dxcompiler.dll', 'dxil.dll',
    'vk_swiftshader.dll', 'vk_swiftshader_icd.json', 'vulkan-1.dll', 'version',
    'locales/en-US.pak', 'locales/pl.pak', 'LICENSE', 'LICENSES.chromium.html']) requireFile(directory, file);
  const archive = path.join(directory, 'resources/app.asar');
  const entries = asar.listPackage(archive).map(name => name.replaceAll('\\', '/').replace(/^\//, ''));
  const read = name => asar.extractFile(archive, path.normalize(name)).toString('utf8');
  const pkg = JSON.parse(read('package.json'));
  assert.equal(pkg.name, metadata.name);
  assert.equal(pkg.version, metadata.version);
  assert.equal(pkg.main, '.vite/build/main.js');
  for (const file of [pkg.main, '.vite/build/preload.js', '.vite/renderer/main_window/index.html']) assert.ok(read(file).length, file);
  const main = read(pkg.main);
  assert.match(main, /node:sqlite/);
  assert.ok(/sandbox:\s*(?:true|!0)/.test(main), 'Sandbox must remain enabled');
  assert.ok(/contextIsolation:\s*(?:true|!0)/.test(main), 'Context isolation must remain enabled');
  assert.ok(/nodeIntegration:\s*(?:false|!1)/.test(main), 'Node integration must remain disabled');
  assert.ok(!main.includes('localhost:'), 'Production main cannot reference a dev server');
  assert.ok(entries.some(name => /discussion-query\.worker-.*\.js$/.test(name)), 'Query worker missing');
  assert.ok(entries.some(name => /assets\/.*\.css$/.test(name)), 'CSS missing');
  const html = read('.vite/renderer/main_window/index.html');
  for (const [, asset] of html.matchAll(/(?:src|href)="\.\/([^"?#]+)"/g)) assert.ok(read(`.vite/renderer/main_window/${asset}`).length, asset);
  assert.ok(!entries.some(name => /^(src|scripts|docs)\//.test(name)), 'Source/test files must not ship');
  const wire = await getCurrentFuseWire(executable);
  for (const [name, state] of Object.entries({ RunAsNode: 48, EnableCookieEncryption: 49, EnableNodeOptionsEnvironmentVariable: 48,
    EnableNodeCliInspectArguments: 48, EnableEmbeddedAsarIntegrityValidation: 49, OnlyLoadAppFromAsar: 49 })) {
    assert.equal(wire[FuseV1Options[name]], state, `Fuse ${name}`);
  }
  const files = filesUnder(directory);
  return { executable, directory, files: files.length, bytes: files.reduce((sum, file) => sum + fs.statSync(path.join(directory, file)).size, 0) };
}
async function verifyZip(archive = zipFile, directory = packageDirectory) {
  requireFile(path.dirname(archive), path.basename(archive), 1000000);
  const expected = new Set(filesUnder(directory));
  const zip = await promisify(yauzl.open)(archive, { lazyEntries: true });
  const watchdog = setTimeout(() => { zip.emit('error', new Error('ZIP validation timed out')); }, 120000);
  try {
    await new Promise((resolve, reject) => {
      zip.on('error', reject);
      zip.on('end', resolve);
      zip.on('entry', async entry => {
        try {
          if (entry.fileName.endsWith('/')) { zip.readEntry(); return; }
          assert.ok(expected.delete(entry.fileName), `Unexpected/duplicate ZIP entry: ${entry.fileName}`);
          const original = fs.readFileSync(path.join(directory, entry.fileName));
          assert.equal(entry.uncompressedSize, original.length, `Truncated ZIP entry: ${entry.fileName}`);
          const stream = await promisify(zip.openReadStream.bind(zip))(entry);
          const hash = crypto.createHash('sha256');
          for await (const chunk of stream) hash.update(chunk);
          assert.equal(hash.digest('hex'), crypto.createHash('sha256').update(original).digest('hex'), `ZIP bytes differ: ${entry.fileName}`);
          zip.readEntry();
        } catch (error) { zip.close(); reject(error); }
      });
      zip.readEntry();
    });
    assert.equal(expected.size, 0, `ZIP missing application files: ${[...expected].join(', ')}`);
    return { archive, bytes: fs.statSync(archive).size };
  } finally { clearTimeout(watchdog); zip.close(); }
}
module.exports = { verifyPackage, verifyZip, packageDirectory, zipFile };
if (require.main === module) (async () => {
  console.log(JSON.stringify(await verifyPackage(), null, 2));
  if (!process.argv.includes('--package-only')) console.log(JSON.stringify(await verifyZip(), null, 2));
})().catch(error => { console.error(error); process.exitCode = 1; });
